_NONCE_SIZE = 12

_K_PARTS = [54, 180, 72, 1, 215, 223, 107, 250, 117, 184, 102, 208, 109, 172, 229, 206, 21, 160, 110, 108, 244, 219, 237, 169, 2, 140, 113, 238, 248, 67, 254, 136]
_K_MASK = [17, 13, 45, 119, 248, 50, 168, 150, 170, 23, 12, 207, 126, 101, 253, 167, 210, 195, 78, 156, 73, 183, 8, 88, 59, 163, 98, 75, 17, 140, 79, 13]

def _rebuild_key():
    parts = _K_PARTS
    mask = _K_MASK
    key = bytes(p ^ m for p, m in zip(parts, mask))
    return key

def _run():
    raw = base64.b85decode(_PAYLOAD)
    nonce, ciphertext = raw[:_NONCE_SIZE], raw[_NONCE_SIZE:]
    key = _rebuild_key()
    aesgcm = AESGCM(key)
    try:
        compressed = aesgcm.decrypt(nonce, ciphertext, None)
    except Exception:
        sys.stderr.write("Corrupted or tampered protected file.\n")
        sys.exit(1)
    raw_bytecode = zlib.decompress(compressed)
    code_obj = marshal.loads(raw_bytecode)
    exec(code_obj, {"__name__": "__main__"})

_run()
